Generate ONLY executable Python function stimulus(rng, cycles) for RTL input stimulus.
Return code only. No imports, classes, prints, external state, HDL, output checking, or DUT reading.
Return exactly 20000 ordered chronological dictionaries. Every row has all the non-clock ports and
unsigned integers in [0, 2**width). Optional 'mid' is a dict that overrides inputs AFTER the rising edge
and before the falling edge. Those values persist until the start of the next row. Clock edges are provided.
Use compact loops and bounded-width arithmetic, including resets and long runs as warranted by the spec.
Widths: {'rst_in': 1, 'enc_valid_in': 1, 'enc_data_in': 8, 'dec_valid_in': 1, 'dec_data_in': 16}. Active reset levels: {'rst_in': 1}.
Fixed parameter bindings: {'N': 8}. This input function must not change parameters.
Seed: 20261125. Keep the function under 85 source lines.
Public spec:

Released RTL:
module top_manchester #(
    parameter N = 8  // Default width of input and output data
) (
    input  logic           clk_in,          // Clock input
    input  logic           rst_in,          // Active high reset input

    // Encoder Signals
    input  logic           enc_valid_in,    // Input valid signal
    input  logic [N-1:0]   enc_data_in,     // N-bit input data
    output logic           enc_valid_out,   // Output valid signal
    output logic [2*N-1:0] enc_data_out,    // 2*N-bit encoder output data

    // Decoder Signals
    input  logic           dec_valid_in,    // Input valid signal
    input  logic [2*N-1:0] dec_data_in,     // 2*N-bit input data
    output logic           dec_valid_out,   // Output valid signal
    output logic [N-1:0]   dec_data_out     // N-bit output decoded data
);

    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            enc_data_out  <= '0; 
            enc_valid_out <= 1'b0; 
        end else if (enc_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i]   <= 1'b1;
                    enc_data_out[2*i+1] <= 1'b0;
                end else begin
                    enc_data_out[2*i]   <= 1'b0;
                    enc_data_out[2*i+1] <= 1'b1;
                end
            end
            enc_valid_out <= 1'b1;
        end else begin
            enc_data_out  <= 'd0;
            enc_valid_out <= 1'b0;
        end
    end

    always_ff @(posedge clk_in) begin
        if (rst_in) begin
            dec_data_out  <= '0; 
            dec_valid_out <= 1'b0;
        end else if (dec_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (dec_data_in[2*i] == 1'b1 && dec_data_in[2*i+1] == 1'b0) begin
                    dec_data_out[i] <= 1'b1;
                end else if (dec_data_in[2*i] == 1'b0 && dec_data_in[2*i+1] == 1'b1) begin
                    dec_data_out[i] <= 1'b0;
                end else begin
                    dec_data_out[i] <= 1'b0;
                end
            end
            dec_valid_out <= 1'b1;
        end else begin
            dec_data_out  <= '0;
            dec_valid_out <= 1'b0;
        end
    end

endmodule
